var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<Catalog>();
builder.Services.AddResponseCaching();
var app = builder.Build();
app.UseResponseCaching();

app.MapGet("/products/featured", async (HttpContext ctx, Catalog catalog) =>
{
    // Also tells browsers and every proxy on the way to keep it
    ctx.Response.Headers.CacheControl = "public, max-age=60";
    return await catalog.GetFeaturedAsync();
});
// A request with "Cache-Control: no-cache" skips the cache entirely
app.Run();

using Microsoft.AspNetCore.OutputCaching;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<Catalog>();
builder.Services.AddOutputCache(o => o.AddPolicy("catalog",
    p => p.Expire(TimeSpan.FromMinutes(1)).Tag("catalog")));
var app = builder.Build();
app.UseOutputCache();

// Stored on the server; request headers can't bypass it
app.MapGet("/products/featured",
    (Catalog catalog) => catalog.GetFeaturedAsync()).CacheOutput("catalog");

app.MapPut("/products/{id:int}", async (int id, Product product,
    Catalog catalog, IOutputCacheStore cache, CancellationToken ct) =>
{
    await catalog.SaveAsync(id, product, ct);
    await cache.EvictByTagAsync("catalog", ct); // next GET rebuilds it
    return Results.NoContent();
});
app.Run();
